"""
Currency Detection Model Training Script
Trains YOLO model to detect Indian currency notes and coins

Dataset: final_dataset/ (11 denominations, built by prepare_final_dataset.py)
"""

from ultralytics import YOLO
import os

import torch

# Dataset generated by prepare_final_dataset.py (clean split, 11 classes)
DATA_YAML = 'final_dataset/dataset.yaml'


def pick_device():
    """Use CUDA when available so a GPU machine never silently trains on CPU"""
    if torch.cuda.is_available():
        print(f"GPU detected: {torch.cuda.get_device_name(0)}")
        return 0
    if getattr(torch.backends, 'mps', None) and torch.backends.mps.is_available():
        print("Apple Silicon GPU detected (mps)")
        return 'mps'
    print("No GPU detected - training on CPU")
    return 'cpu'

def check_dataset():
    """Verify the prepared dataset exists before training"""
    if not os.path.exists(DATA_YAML):
        print(f"ERROR: {DATA_YAML} not found.")
        print("Build it first: python prepare_final_dataset.py")
        raise SystemExit(1)
    print(f"Using dataset config: {DATA_YAML}")

def train_model(epochs=100, img_size=640, batch_size=16):
    """
    Train YOLO model for currency detection
    
    Args:
        epochs: Number of training epochs
        img_size: Input image size
        batch_size: Batch size for training
    """
    
    # Load pre-trained YOLOv8 model
    print("Loading YOLOv8 model...")
    model = YOLO('yolov8n.pt')  # Using nano version for faster inference
    
    # Train the model
    print("Starting training...")
    results = model.train(
        data=DATA_YAML,
        epochs=epochs,
        imgsz=img_size,
        batch=batch_size,
        device=pick_device(),
        workers=4,
        optimizer='SGD',
        lr0=0.01,
        lrf=0.1,
        momentum=0.937,
        weight_decay=0.0005,
        warmup_epochs=3.0,
        patience=50,
        project='runs/detect',
        name='currency_detection',
        exist_ok=True,
        verbose=True
    )
    
    print("Training completed!")
    print(f"Best model saved at: {results.save_dir}/weights/best.pt")
    
    return results

def validate_model(model_path, val_images_path):
    """Validate the trained model"""
    
    print("Validating model...")
    model = YOLO(model_path)
    
    # Run validation
    metrics = model.val(data=DATA_YAML)
    
    print(f"mAP50: {metrics.box.map50}")
    print(f"mAP50-95: {metrics.box.map}")
    
    return metrics

if __name__ == "__main__":
    import argparse
    
    parser = argparse.ArgumentParser(description='Train Currency Detection Model')
    parser.add_argument('--epochs', type=int, default=100,
                        help='Number of training epochs')
    parser.add_argument('--img_size', type=int, default=640,
                        help='Input image size')
    parser.add_argument('--batch_size', type=int, default=16,
                        help='Batch size')
    
    args = parser.parse_args()
    
    # Verify prepared dataset exists
    check_dataset()
    
    # Train the model
    train_model(
        epochs=args.epochs,
        img_size=args.img_size,
        batch_size=args.batch_size
    )
    
    print("\n" + "="*50)
    print("Training Pipeline Completed Successfully!")
    print("="*50)
    print("\nNext steps:")
    print("1. Run the Flask server: python app.py")
    print("2. Open browser and access the web application")
    print("3. Allow camera permissions")
    print("4. Show currency notes to camera for real-time detection")
